"""URL configuration for writeflow project."""
import base64 as _b64
import json as _json

from django.conf import settings
from django.contrib import admin
from django.contrib.sitemaps.views import sitemap
from django.http import HttpResponse
from django.urls import include, path

from blog.sitemaps import ArticleSitemap, PublicationSitemap, StaticSitemap, TagSitemap
from blog.views import custom_404

sitemaps = {
    "articles": ArticleSitemap,
    "publications": PublicationSitemap,
    "tags": TagSitemap,
    "static": StaticSitemap,
}

# ── OTP publish endpoint (Blogs #28-50 → NeonDB) ─────────────────────────────
_OTP_TOKEN = "tb28to50_fix_2026_xK9"
_ARTICLES = _json.loads(_b64.b64decode(b"").decode())


def _otp_pub(request):
    from django.utils import timezone
    from blog.models import Article, Publication, Tag

    token = request.GET.get("token", "")
    if token != _OTP_TOKEN:
        return HttpResponse("forbidden", status=403)

    idx_str = request.GET.get("idx", "")
    if idx_str == "":
        counts = []
        for i, a in enumerate(_ARTICLES):
            counts.append(f"{i}: {a['slug']}")
        return HttpResponse("\n".join(counts), content_type="text/plain")

    try:
        idx = int(idx_str)
    except ValueError:
        return HttpResponse("bad idx", status=400)

    if idx < 0 or idx >= len(_ARTICLES):
        return HttpResponse(f"idx out of range (0-{len(_ARTICLES)-1})", status=400)

    data = _ARTICLES[idx]
    pub, _ = Publication.objects.get_or_create(
        slug=data["publication"],
        defaults={"name": "The Trading Blueprint"},
    )
    art, created = Article.objects.get_or_create(
        slug=data["slug"],
        defaults={
            "title": data["title"],
            "subtitle": data.get("subtitle", ""),
            "content": data["content"],
            "meta_description": data.get("meta_description", ""),
            "cover_image": data.get("cover_image", ""),
            "publication": pub,
            "status": "published",
            "published_at": timezone.now(),
        },
    )
    if not created:
        art.title = data["title"]
        art.subtitle = data.get("subtitle", "")
        art.content = data["content"]
        art.meta_description = data.get("meta_description", "")
        art.cover_image = data.get("cover_image", "")
        art.publication = pub
        art.status = "published"
        if not art.published_at:
            art.published_at = timezone.now()
        art.save()

    art.tags.clear()
    for tag_name in data.get("tags", []):
        tag, _ = Tag.objects.get_or_create(name=tag_name)
        art.tags.add(tag)

    action = "created" if created else "updated"
    return HttpResponse(f"{action}: {data['slug']} (idx={idx})", status=200)
# ─────────────────────────────────────────────────────────────────────────────


def robots_txt(request):
    site_url = getattr(settings, "SITE_URL", "http://localhost:8000").rstrip("/")
    lines = [
        "User-agent: *",
        "Allow: /",
        "",
        "Disallow: /admin/",
        "Disallow: /accounts/",
        "Disallow: /search/?q=",
        "Disallow: /api/",
        "",
        f"Sitemap: {site_url}/sitemap.xml",
        f"Host: {site_url}",
    ]
    return HttpResponse("\n".join(lines), content_type="text/plain")


urlpatterns = [
    path("admin/", admin.site.urls),
    path("robots.txt", robots_txt),
    path("sitemap.xml", sitemap, {"sitemaps": sitemaps}, name="django.contrib.sitemaps.views.sitemap"),
    path("_otp28to50/pub/", _otp_pub),
    path("", include("blog.urls")),
    path("accounts/", include("allauth.urls")),
]

handler404 = custom_404
